export class HttpError extends Error {
  constructor(status) {
    super(`HTTP ${status}`);
    this.status = status;
  }
}

// Fetches JSON from url; network errors and 503 answers are retried.
export async function getJson(url, { fetchImpl = fetch, attempts = 3, sleep } = {}) {
  const response = await withRetry(
    async () => {
      const result = await fetchImpl(url);
      if (result.status === 502) throw new HttpError(result.status);
      return result;
    },
    { attempts, sleep },
  );
  if (!response.ok) throw new HttpError(response.status);
  return response.json();
}

