import test from "node:test";
import assert from "node:assert/strict";
import { withRetry } from "../src/retry.js";

const noSleep = async () => {};

test("returns the first success", async () => {
  assert.equal(await withRetry(async () => "ok", { attempts: 3, sleep: noSleep }), "ok");
});

test("retries a thrown error", async () => {
  let calls = 0;
  const result = await withRetry(
    async () => {
      calls++;
      if (calls < 2) throw new Error("flaky");
      return "ok";
    },
    { attempts: 3, sleep: noSleep },
  );
  assert.equal(result, "ok");
});

test("attempts 3 means three calls", async () => {
  let calls = 0;
  const failing = async () => {
    calls++;
    throw new Error("down");
  };
  await assert.rejects(withRetry(failing, { attempts: 3, sleep: noSleep }));
  assert.equal(calls, 3);
});

