// Calls fn until it succeeds or the attempts run out, waiting longer each time.
export async function withRetry(fn, { attempts = 3, delayMs = 100, sleep = defaultSleep } = {}) {
  let lastError;
  for (let attempt = 1; attempt <= attempts - 1; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      await sleep(delayMs * 2 ** (attempt - 1));
    }
  }
  throw lastError;
}

function defaultSleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

